# Java工具类

```java
package net.tv90.util.html;

import lombok.NonNull;

import java.util.Map;

public class ShieldsIOUtil {

    /**
     * 生成超链接数据牌
     * @param url 超链接地址 null为#
     * @param label 数据牌标签
     * @param color 数据牌颜色
     * @param logo 数据牌LOGO
     * @return HTML代码
     */
    public static String generateBasicShieldHTML(String url, String label, String color, String logo){
        if(url == null) url = "#";
        if(label == null) label = "label";
        if(color == null) color = "black";
        StringBuilder html = new StringBuilder("<a href=\"" + url + "\" target=\"_blank\"><img src=\"https://img.shields.io/badge/" + label + "-" + color);
        if(logo != null) html.append("?logo=").append(logo);
        html.append("\"></a>");
        return html.toString();
    }

    /**
     * 生成超链接数据牌
     * @param url 超链接地址 null为#
     * @param label1 数据牌标签1
     * @param label2 数据牌标签2
     * @param color 数据牌颜色
     * @param logo 数据牌LOGO
     * @return HTML代码
     */
    public static String generateBasicShieldHTML(String url, String label1, String label2, String color, String logo){
        if(url == null) url = "#";
        if(label1 == null) label1 = "label1";
        if(label2 == null) label2 = "label2";
        if(color == null) color = "black";
        StringBuilder html = new StringBuilder("<a href=\"" + url + "\" target=\"_blank\"><img src=\"https://img.shields.io/badge/" + label1 + "-" + label2 + "-" + color);
        if(logo != null) html.append("?logo=").append(logo);
        html.append("\"></a>");
        return html.toString();
    }

    /**
     * 生成自定义数据牌
     * @param htmlLabel 外层HTML标签 null为span，可填写div，a，p等等
     * @param htmlAttributes 外层HTML标签属性
     * @param label 数据牌标签
     * @param color 数据牌颜色
     * @param logo 数据牌logo
     * @return HTML代码
     */
    public static String generateCustomShieldHTML(String htmlLabel, Map<?, ?> htmlAttributes, String label, String color, String logo){
        if(htmlLabel == null) htmlLabel = "span";
        if(label == null) label = "label";
        if(color == null) color = "black";
        StringBuilder html = new StringBuilder("<" + htmlLabel + mapToHTMLAttributes(htmlAttributes) + "><img src=\"https://img.shields.io/badge/" + label + "-" + color);
        if(logo != null) html.append("?logo=").append(logo);
        html.append("\"></").append(htmlLabel).append(">");
        return html.toString();
    }

    /**
     * 生成自定义数据牌
     * @param htmlLabel 外层HTML标签 null为span，可填写div，a，p等等
     * @param htmlAttributes 外层HTML标签属性
     * @param label1 数据牌标签1
     * @param label2 数据牌标签2
     * @param color 数据牌颜色
     * @param logo 数据牌logo
     * @return HTML代码
     */
    public static String generateCustomShieldHTML(String htmlLabel, Map<?, ?> htmlAttributes, String label1, String label2, String color, String logo){
        if(htmlLabel == null) htmlLabel = "span";
        if(label1 == null) label1 = "label1";
        if(label2 == null) label2 = "label2";
        if(color == null) color = "black";
        StringBuilder html = new StringBuilder("<" + htmlLabel + mapToHTMLAttributes(htmlAttributes) + "><img src=\"https://img.shields.io/badge/" + label1 + "-" + label2 + "-" + color);
        if(logo != null) html.append("?logo=").append(logo);
        html.append("\"></").append(htmlLabel).append(">");
        return html.toString();
    }

    /**
     * 生成响应JSON数据的数据牌
     * @param url 超链接地址 null为#
     * @param requestURL 请求地址 不能为null
     * @param query 响应数据的JSON key
     * @param label 数据牌标签
     * @param color 数据牌颜色
     * @param logo 数据牌logo
     * @return HTML标签
     */
    public static String generateBasicResponseShieldHTML(String url, @NonNull String requestURL, @NonNull String query,
                                                     String label, String color, String logo){
        if(url == null) url = "#";

        StringBuilder urlAttr = new StringBuilder();
        if(logo != null) urlAttr.append("&logo=").append(logo);
        if(label != null) urlAttr.append("&label=").append(label);
        if(color != null) urlAttr.append("&color=").append(color);
        urlAttr.append("&query=").append(query);
        urlAttr.append("&url=").append(requestURL);
        urlAttr = new StringBuilder(urlAttr.substring(1, urlAttr.length()));

        return "<a href=\"" + url + "\" target=\"_blank\"><img src=\"https://img.shields.io/badge/dynamic/json?" + urlAttr + "\"></a>";
    }

    /**
     * 生成响应JSON数据的自定义数据牌
     * @param htmlLabel 外层HTML标签 null为span，可填写div，a，p等等
     * @param htmlAttributes 外层HTML标签属性
     * @param requestURL 请求地址 不能为null
     * @param query 响应数据的JSON key
     * @param label 数据牌标签
     * @param color 数据牌颜色
     * @param logo 数据牌logo
     * @return HTML标签
     */
    public static String generateCustomResponseShieldHTML(String htmlLabel, Map<?, ?> htmlAttributes, @NonNull String requestURL, @NonNull String query,
                                                      String label, String color, String logo){
        if(htmlLabel == null) htmlLabel = "span";

        StringBuilder urlAttr = new StringBuilder();
        if(logo != null) urlAttr.append("&logo=").append(logo);
        if(label != null) urlAttr.append("&label=").append(label);
        urlAttr.append("&query=").append(query);
        urlAttr.append("&url=").append(requestURL);
        urlAttr = new StringBuilder(urlAttr.substring(1, urlAttr.length()));

        return "<" + htmlLabel + mapToHTMLAttributes(htmlAttributes) + "><img src=\"https://img.shields.io/badge/dynamic/json?" + urlAttr + "\"></"+ htmlLabel +">";
    }

    /**
     * Map集合转换为HTML标签上面的属性
     * @param map 集合
     * @return HTML标签属性
     */
    public static String mapToHTMLAttributes(Map<?, ?> map){
        if(map == null) return "";
        StringBuilder sb = new StringBuilder();
        map.forEach((K,V) -> sb.append(" ").append(K.toString()).append("=\"").append(V.toString()).append("\""));
        return sb.toString();
    }

}
